edits.newText:
// --- Issue #1: the ball bounces off bricks instead of plowing through ---------

const R = 7; // BALL_R

// A brick in the middle of the field, wide enough that the ball never touches
// a seam when centred on it.
function brick() {
  return { x: 100, y: 100, w: 40, h: 20, alive: true };
}

test('#1 top hit: flips vy, leaves vx untouched, pushes the ball out', () => {
  const ball = { x: 120, y: 96, r: R, vx: 120, vy: 300, px: 120, py: 80 };
  const b = brick();
  const hit = brickHit(ball, [b]);
  assert.equal(hit.length, 1);
  assert.equal(hit[0], b);
  assert.equal(b.alive, false);
  assert.equal(ball.vy, -300, 'vy must flip on a top hit');
  assert.equal(ball.vx, 120, 'vx must be left exactly as it was');
  assert.equal(ball.y, b.y - R, 'ball pushed back out above the brick');
  assert.equal(collides(ball, b), false);
});

test('#1 bottom hit: flips vy back down', () => {
  const ball = { x: 120, y: 124, r: R, vx: -40, vy: -300, px: 120, py: 140 };
  const b = brick();
  brickHit(ball, [b]);
  assert.equal(ball.vy, 300, 'vy must flip on a bottom hit');
  assert.equal(ball.vx, -40, 'vx must be left exactly as it was');
  assert.equal(ball.y, b.y + b.h + R, 'ball pushed back out below the brick');
});

test('#1 side hit (left face): flips vx, leaves vy untouched', () => {
  const ball = { x: 96, y: 110, r: R, vx: 300, vy: 60, px: 80, py: 110 };
  const b = brick();
  brickHit(ball, [b]);
  assert.equal(ball.vx, -300, 'vx must flip on a side hit');
  assert.equal(ball.vy, 60, 'vy must be left exactly as it was');
  assert.equal(ball.x, b.x - R, 'ball pushed back out to the left of the brick');
});

test('#1 side hit without history: smallest penetration decides the face', () => {
  const ball = { x: 103, y: 110, r: R, vx: 300, vy: 0 }; // 3 px into the left face
  const b = brick();
  brickHit(ball, [b]);
  assert.equal(ball.vx, -300, 'the smaller penetration is the side face');
  assert.equal(ball.vy, 0);
  assert.equal(ball.x, b.x - R);
});

test('#1 corner: equal penetrations flip both components', () => {
  const ball = { x: 100, y: 100, r: R, vx: 300, vy: 300 }; // exactly on the corner
  const b = brick();
  brickHit(ball, [b]);
  assert.equal(ball.vx, -300, 'diagonal hit flips vx');
  assert.equal(ball.vy, -300, 'diagonal hit flips vy');
  assert.equal(ball.x, b.x - R);
  assert.equal(ball.y, b.y - R);
});

test('#1 neighbours: a seam overlaps two bricks, the bounce applies exactly once', () => {
  const a = brick();
  const b = { x: 148, y: 100, w: 40, h: 20, alive: true }; // 8 px gap at [140, 148]
  const ball = { x: 144, y: 96, r: R, vx: 40, vy: 400, px: 144, py: 80 };
  const hit = brickHit(ball, [a, b]);
  assert.equal(hit.length, 2, 'both seam bricks are destroyed in the same pass');
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.equal(ball.vy, -400, 'vy flipped exactly once (twice would cancel out)');
  assert.equal(ball.vx, 40, 'vx untouched');
  assert.equal(collides(ball, a), false);
  assert.equal(collides(ball, b), false);
});

test('#1 tunnelling: a fast move jumps over the brick, the sweep still catches it', () => {
  // 50 px in one frame vs 34 px (BRICK_H + diameter) needed to cross.
  const ball = { x: 120, y: 130, r: R, vx: 0, vy: 700, px: 120, py: 80 };
  const b = brick();
  const hit = brickHit(ball, [b]);
  assert.equal(hit.length, 1);
  assert.equal(b.alive, false);
  assert.equal(ball.vy, -700, 'the ball bounces back up');
  assert.ok(ball.y < b.y, 'the ball is repositioned at the entry face, above the brick');
  assert.equal(collides(ball, b), false);
});

test('#1 push out: after resolution the ball overlaps no live brick', () => {
  const bricks = [
    brick(),
    { x: 148, y: 100, w: 40, h: 20, alive: true },
    { x: 196, y: 100, w: 40, h: 20, alive: true },
  ];
  const ball = { x: 146, y: 96, r: R, vx: 0, vy: 400, px: 146, py: 80 };
  brickHit(ball, bricks);
  const live = bricks.filter((b) => b.alive);
  assert.ok(
    live.every((b) => !collides(ball, b)),
    'no live brick still overlaps the ball after the push-out',
  );
});

test('#1 horizontal shot at a row seam bounces off the side, not vertically', () => {
  // Ball is 14 px across, the row gap is 8 px: the ball grazes two rows at
  // once, but the bounce must follow the motion (side face), not the
  // shallow vertical overlap — otherwise the ball plows through the row.
  const top = brick();
  const bottom = { x: 100, y: 128, w: 40, h: 20, alive: true }; // gap [120, 128]
  const ball = { x: 103, y: 124, r: R, vx: 300, vy: 0, px: 80, py: 124 };
  const hit = brickHit(ball, [top, bottom]);
  assert.equal(hit.length, 2, 'both rows are brushed');
  assert.equal(ball.vx, -300, 'the ball bounces off the side of the wall');
  assert.equal(ball.vy, 0, 'vy untouched: the ball was moving sideways');
});

test('#1 no contact: an away ball is untouched', () => {
  const ball = { x: 300, y: 300, r: R, vx: -100, vy: 100, px: 290, py: 290 };
  const b = brick();
  const hit = brickHit(ball, [b]);
  assert.equal(hit.length, 0);
